<script setup lang="ts">
import {Head} from '@inertiajs/vue3';import {computed,onMounted,ref} from 'vue';import {Braces,ChevronDown,ChevronUp,Play,RefreshCw,ShieldCheck,Wifi} from 'lucide-vue-next';
defineOptions({layout:{breadcrumbs:[{title:'Dashboard',href:'/dashboard'},{title:'Tools',href:'/tools'},{title:'API Tester',href:'/tools/api'}]}});
type E={method:string;path:string;title:string;group:string;auth:boolean;body:string};
const endpoints=ref<E[]>([]),token=ref(''),open=ref<number|null>(0),bodies=ref<Record<number,string>>({}),running=ref<number|null>(null),loading=ref(false),responses=ref<Record<number,{status:number;ms:number;body:string}>>({});
const grouped=computed(()=>Object.entries(endpoints.value.reduce((a,e,i)=>{(a[e.group]??=[]).push({e,i});return a},{} as Record<string,{e:E;i:number}[]>)));
async function loadSpec(){loading.value=true;try{const r=await fetch('/api/v1/tools/openapi.json',{headers:{Accept:'application/json'}}),j=await r.json();if(!r.ok)throw new Error(j.message??'Unable to load API routes');const list:E[]=[];for(const [path,ops] of Object.entries(j.paths??{}))for(const [method,op] of Object.entries(ops as any)){const o:any=op;if(!['get','post','put','patch','delete'].includes(method))continue;list.push({method:method.toUpperCase(),path,title:o.summary??path,group:o.tags?.[0]??'API',auth:!!o.security,body:['POST','PUT','PATCH'].includes(method.toUpperCase())?'{}':''})}endpoints.value=list;list.forEach((e,i)=>bodies.value[i]=e.body)}catch(err:any){responses.value[-1]={status:0,ms:0,body:err.message??'Unable to load API specification'}}finally{loading.value=false}}
onMounted(loadSpec);
async function run(e:E,i:number){running.value=i;const start=performance.now();try{const h:Record<string,string>={Accept:'application/json'};if(e.auth&&token.value)h.Authorization='Bearer '+token.value;if(['POST','PUT','PATCH'].includes(e.method))h['Content-Type']='application/json';const r=await fetch('/api/v1'+e.path,{method:e.method,headers:h,body:['POST','PUT','PATCH'].includes(e.method)?bodies.value[i]:undefined});const text=await r.text();let pretty=text;try{pretty=JSON.stringify(JSON.parse(text),null,2)}catch{}responses.value[i]={status:r.status,ms:Math.round(performance.now()-start),body:pretty||'(empty response)'}}catch(err:any){responses.value[i]={status:0,ms:Math.round(performance.now()-start),body:err.message??'Request failed'}}finally{running.value=null}}
</script>
<template><Head title="Tools — API Tester"/><main class="api-workspace">
<header class="hero"><div><p class="eyebrow"><Wifi :size="14"/> BYPASS GRILL / DEVELOPER TOOLS</p><h1>API <em>workspace.</em></h1><p>Live endpoint discovery from the registered Laravel API routes.</p></div><div class="hero-actions"><div class="live"><span></span>LIVE API <small>/api/v1</small></div><button class="refresh" :disabled="loading" @click="loadSpec"><RefreshCw :size="14"/>{{loading?'REFRESHING…':'REFRESH ROUTES'}}</button></div></header>
<section class="auth"><div><ShieldCheck :size="18"/><div><strong>Bearer token</strong><small>Used only for protected requests in this browser.</small></div></div><input v-model="token" type="password" placeholder="Paste Android POS token"/></section>
<div v-if="responses[-1]" class="response errorbox"><pre>{{responses[-1].body}}</pre></div><p v-if="loading&&!endpoints.length" class="empty">Discovering registered API routes…</p>
<section v-for="[group,rows] in grouped" :key="group" class="group"><div class="group-title"><span>{{group}}</span><small>{{rows.length}} endpoints</small></div>
<article v-for="{e,i} in rows" :key="e.method+e.path" class="endpoint"><button class="endpoint-head" @click="open=open===i?null:i"><span :class="['method',e.method.toLowerCase()]">{{e.method}}</span><code>{{e.path}}</code><span class="desc">{{e.title}}</span><span v-if="e.auth" class="protected">AUTH</span><ChevronUp v-if="open===i" :size="17"/><ChevronDown v-else :size="17"/></button>
<div v-if="open===i" class="endpoint-body"><div v-if="['POST','PUT','PATCH'].includes(e.method)" class="editor"><label><Braces :size="14"/> REQUEST BODY</label><textarea v-model="bodies[i]" spellcheck="false"/></div><button class="send" :disabled="running===i" @click="run(e,i)"><Play :size="14"/>{{running===i?'SENDING…':'SEND REQUEST'}}</button>
<div v-if="responses[i]" class="response"><div><strong>RESPONSE</strong><span :class="responses[i].status>=200&&responses[i].status<300?'ok':'bad'">{{responses[i].status||'ERR'}}</span><small>{{responses[i].ms}} ms</small></div><pre>{{responses[i].body}}</pre></div></div></article></section></main></template>
<style scoped>
.api-workspace{padding:clamp(16px,3vw,38px);max-width:1400px;width:100%;margin:auto}.hero{display:flex;justify-content:space-between;gap:24px;align-items:end;border-bottom:1px solid var(--border);padding-bottom:28px;margin-bottom:22px}.eyebrow{display:flex;align-items:center;gap:7px;font-size:11px;font-weight:800;letter-spacing:.14em;color:#a3472d}.hero h1{font-size:clamp(34px,5vw,58px);font-weight:800;letter-spacing:-.045em;line-height:1;margin:10px 0}.hero h1 em{font-family:Georgia,serif;font-weight:400}.hero>div>p:last-child{color:var(--muted-foreground);font-size:14px}.hero-actions{display:flex;gap:8px;align-items:center}.live,.refresh{border:1px solid var(--border);border-radius:999px;padding:9px 13px;font-size:11px;font-weight:800;display:flex;align-items:center;gap:7px}.live span{width:7px;height:7px;border-radius:50%;background:#39a75c}.live small{color:var(--muted-foreground);font-family:monospace}.refresh{background:var(--card)}.auth{display:flex;align-items:center;gap:18px;padding:16px;border:1px solid var(--border);border-radius:14px;background:var(--card);margin-bottom:28px}.auth>div{display:flex;align-items:center;gap:10px;min-width:220px}.auth strong,.auth small{display:block}.auth small{font-size:11px;color:var(--muted-foreground);margin-top:2px}.auth input{flex:1;min-width:0;border:1px solid var(--border);background:var(--background);border-radius:9px;padding:10px 12px;font:12px monospace;color:var(--foreground)}.group{margin:28px 0}.group-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px;font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.09em}.group-title small{color:var(--muted-foreground);font-weight:500;text-transform:none;letter-spacing:0}.endpoint{border:1px solid var(--border);background:var(--card);margin-top:-1px;overflow:hidden}.endpoint:first-of-type{border-radius:12px 12px 0 0}.endpoint:last-of-type{border-radius:0 0 12px 12px}.endpoint-head{width:100%;display:grid;grid-template-columns:62px minmax(150px,1fr) minmax(180px,1fr) auto auto;gap:12px;align-items:center;padding:14px;text-align:left}.method{font-size:10px;font-weight:900;letter-spacing:.05em}.method.get{color:#24734b}.method.post{color:#a3472d}.method.put,.method.patch{color:#9a6a13}.method.delete{color:#b42318}.endpoint code{font-size:12px;font-weight:700}.desc{font-size:12px;color:var(--muted-foreground)}.protected{font-size:9px;font-weight:800;border:1px solid var(--border);border-radius:999px;padding:4px 7px}.endpoint-body{border-top:1px solid var(--border);padding:16px;background:color-mix(in srgb,var(--muted) 28%,transparent)}.editor label{display:flex;gap:6px;align-items:center;font-size:10px;font-weight:800;margin-bottom:7px}.editor textarea{width:100%;min-height:150px;border:1px solid var(--border);border-radius:10px;background:var(--background);color:var(--foreground);padding:13px;font:12px/1.6 monospace;resize:vertical}.send{display:flex;align-items:center;gap:7px;margin-top:11px;background:#a3472d;color:white;border-radius:9px;padding:10px 14px;font-size:11px;font-weight:900}.send:disabled{opacity:.55}.response{margin-top:16px}.response>div{display:flex;gap:9px;align-items:center;font-size:10px}.response>div strong{letter-spacing:.08em}.response .ok{color:#24734b;font-weight:900}.response .bad{color:#b42318;font-weight:900}.response small{color:var(--muted-foreground)}pre{margin-top:7px;padding:14px;border:1px solid var(--border);border-radius:10px;background:var(--background);font:11px/1.55 monospace;overflow:auto;max-height:380px;white-space:pre-wrap;word-break:break-word}.empty{text-align:center;color:var(--muted-foreground);padding:30px}.errorbox{color:#b42318}
@media(max-width:700px){.api-workspace{padding:16px 14px 36px}.hero{align-items:start;flex-direction:column}.hero-actions{flex-wrap:wrap}.auth{align-items:stretch;flex-direction:column;gap:12px}.auth>div{min-width:0}.endpoint-head{grid-template-columns:52px minmax(0,1fr) auto;padding:13px 12px;gap:8px}.endpoint-head code{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.desc{grid-column:2/4}.protected{display:none}.endpoint-body{padding:12px}.editor textarea{min-height:180px}.send{width:100%;justify-content:center;padding:13px}.response pre{max-height:300px}.hero h1{font-size:38px}}
</style>
